def k(m): return json.dumps(m, ensure_ascii=False, sort_keys=True)
def text_of(m):
    c=m.get("content") if isinstance(m,dict) else None
    if isinstance(c,list): return "".join(p.get("text","") if isinstance(p,dict) else str(p) for p in c)
    return c or ""
def answers_of(d):
    lines=[d["messages"]]+list(d.get("side_calls") or [])
    ks=[[k(m) for m in line] for line in lines]
    out=[]
    for i,ki in enumerate(ks):
        if any(j!=i and len(kj)>len(ki) and kj[:len(ki)]==ki for j,kj in enumerate(ks)): continue
        last=lines[i][-1]
        if last.get("tool_calls"): continue      # dead branch / unfinished draw
        out.append(text_of(last))
    return out

def vote(answers, composed):
    votes={}
    for t in answers:
        a=final_answer_field(t)
        if not a: key=("raw", t.strip().lower())
        elif composed:
            items=tuple(sorted(i.lower() for i in answer_items(a)))
            key=items if items else ("s", a.strip().lower())
        else: key=("s", a.strip().lower())
        votes.setdefault(key, []).append(t)
    return max(votes.values(), key=len)[0] if votes else ""

def item_vote(answers, composed, rule):
    """aggregate items across draws"""
    sets=[]
    for t in answers:
        a=final_answer_field(t)
        if a:
            sets.append([i for i in answer_items(a)])
    n=len(answers)
    counts=collections.Counter()
    for s in sets:
        for i in set(s): counts[i]+=1
    keep=[i for i,c in counts.items() if rule(c,n)]
    # order by first appearance in the plurality answer to keep a natural spelling
    first={}
    for s in sets:
        for i in s: first.setdefault(i, len(first))
    keep.sort(key=lambda i: first[i])
    return ";".join(keep)

for task in ("LawBench","USPTO"):
    mem=json.load(open(f"{task}/memory.json")); prof=mem["answer_profile"]
    composed=bool(joining_separator(prof.get("answers") or {}))
