    print("==",task,"trusted",rep,"/",len(ok),"composed",composed)
    for name,rule in (("majority>n/2",lambda c,n: 2*c>n),(">=all",lambda c,n: c==n),(">=2",lambda c,n: c>=2)):
        good=0
